      const normF = normalize2(f);
      const hasOutgoing = (dag[f] || []).length > 0;
      const hasIncoming = fileKeys.some((other) => other !== f && (dag[other] || []).some((d) => normalize2(d) === normF));
      return !hasOutgoing && !hasIncoming;
