    for (const [path45, content] of fileEntries) {
      if (path45.includes("f45") && content.includes("modifyCertified")) {
        crossLayerViolations++;
        antiPatterns.push(`Unauthorized mutation of certified funnel in ${path45}`);
      }
      if (content.includes("bypassSafetyGate") || content.includes("ignoreAuth")) {
        crossLayerViolations++;
        antiPatterns.push(`Safety gate bypass pattern detected in ${path45}`);
      }
    }
    const certifiedLayerIsolationMaintained = crossLayerViolations === 0;
    if (!certifiedLayerIsolationMaintained) {
      recommendations.push("Restore strict boundary isolation for all certified F1\u2013F45 modules.");
    } else {
      recommendations.push("Maintain strict unidirectional dependency flow from UI -> Orchestrator -> Adapters.");
    }
