import * as crypto25 from "crypto";
var TheMGEvidenceSynthesizer = class {
  /**
   * Transforms raw planning scope and evidence items into verified facts and observed failures.
   */
  synthesizeEvidence(scope) {
    const facts = [];
    const failures = [];
    const hypotheses = [];
    if (scope.evidenceItems) {
      for (const item of scope.evidenceItems) {
        if (item.classification === "VERIFIED_FACT") {
          facts.push({
            factId: item.id,
            statement: item.summary,
            verifiedSource: item.source,
            contentHash: item.contentHash,
            timestamp: Date.now()
          });
        } else if (item.classification === "OBSERVED_FAILURE") {
          failures.push({
            failureId: item.id,
            symptom: item.summary,
            testOrGateReference: item.source,
            severity: item.metadata?.severity || "MAJOR",
            rawErrorSnippet: item.metadata?.rawSnippet
          });
        } else if (item.classification === "HYPOTHESIS") {
          hypotheses.push({
            hypothesisId: item.id,
            premise: item.summary,
            testablePrediction: item.metadata?.prediction || "Observable improvement",
            falsificationCriteria: item.metadata?.falsification || "Failure remains reproducible",
            associatedFailures: item.metadata?.associatedFailures || []
          });
        }
      }
    }
    if (scope.rawFailures) {
      for (let i = 0; i < scope.rawFailures.length; i++) {
        const raw = scope.rawFailures[i];
        const hash = crypto25.createHash("sha256").update(raw).digest("hex");
        failures.push({
          failureId: `FAIL_RAW_${i}_${hash.slice(0, 8)}`,
          symptom: raw,
          testOrGateReference: "RAW_INPUT_REPORT",
          severity: "MAJOR"
        });
      }
    }
    if (scope.rawTestReports) {
      for (let i = 0; i < scope.rawTestReports.length; i++) {
        const rep = scope.rawTestReports[i];
        const hash = crypto25.createHash("sha256").update(rep).digest("hex");
        facts.push({
          factId: `FACT_TEST_REP_${i}`,
          statement: `Test Report recorded: ${rep.slice(0, 100)}`,
          verifiedSource: "TEST_HARNESS",
          contentHash: hash,
          timestamp: Date.now()
        });
      }
    }
    return {
      facts: Object.freeze(facts),
      failures: Object.freeze(failures),
      hypotheses: Object.freeze(hypotheses)
    };
  }
};

// src/cubio/agents/themg/gapIdentifier.ts
var TheMGGapIdentifier = class {
  /**
   * Identifies gaps and generates structured unresolved questions.
   */
  identifyGaps(scope, facts, failures) {
    const questions = [];
    const gaps = [];
    const contradictions = [];
    for (const failure of failures) {
      gaps.push(`Defect: ${failure.symptom}`);
      questions.push({
        questionId: `Q_${failure.failureId}`,
        question: `What is the minimal non-breaking intervention to resolve: "${failure.symptom}"?`,
        impact: `Resolves ${failure.severity} failure in ${failure.testOrGateReference}`,
        recommendedInvestigationStep: `Inspect stack traces and assertions in ${failure.testOrGateReference}`
      });
    }
    for (const fact of facts) {
      for (const failure of failures) {
        const factText = `${fact.statement} ${fact.verifiedSource}`.toLowerCase();
        const failureText = `${failure.symptom} ${failure.testOrGateReference}`.toLowerCase();
        const targets = ["db", "database", "address369", "regression", "spatial", "lockout", "actuation", "performance", "memory"];
        for (const target of targets) {
          if (factText.includes(target) && failureText.includes(target) && (factText.includes("pass") || factText.includes("frozen") || factText.includes("zero") || factText.includes("unmutated") || factText.includes("verified") || factText.includes("clean") || factText.includes("locked")) && (failureText.includes("fail") || failureText.includes("corrupt") || failureText.includes("drift") || failureText.includes("breach") || failureText.includes("error") || failureText.includes("violation"))) {
            const contradictionMsg = `Contradictory evidence detected on '${target}': Fact [${fact.factId}] asserts integrity while Failure [${failure.failureId}] records defect.`;
            contradictions.push(contradictionMsg);
            gaps.push(`Contradiction: ${contradictionMsg}`);
            questions.push({
              questionId: `Q_CONTRADICTION_${target.toUpperCase()}_${fact.factId}_${failure.failureId}`,
              question: `How to reconcile contradictory finding on '${target}' between fact (${fact.factId}) and failure (${failure.failureId})?`,
              impact: "High uncertainty: potential regression mask or invalidated test assumption",
              recommendedInvestigationStep: `Execute clean baseline verification for ${target} before proceeding.`
            });
            break;
          }
        }
      }
    }
    if (scope.dependencies && scope.dependencies.length > 0) {
      for (const dep of scope.dependencies) {
        const isUnresolved = dep.includes("UNRESOLVED") || dep.includes("MISSING") || dep.toLowerCase().includes("pending") || dep.toLowerCase().includes("blocked");
        if (isUnresolved) {
          gaps.push(`Unresolved dependency: ${dep}`);
          questions.push({
            questionId: `Q_DEP_${dep.replace(/[^a-zA-Z0-9_]/g, "_")}`,
            question: `How will unresolved dependency '${dep}' be satisfied prior to execution?`,
            impact: "Execution blocking dependency",
            recommendedInvestigationStep: `Resolve or stub '${dep}' via DRA/PMA before implementation.`
          });
        }
      }
    }
    if (facts.length === 0 && failures.length === 0) {
      gaps.push("Insufficient evidence: no verified facts or prior test records supplied.");
      questions.push({
        questionId: "Q_BASELINE_EVIDENCE",
        question: "What baseline tests or benchmarks exist for this objective?",
        impact: "Prevents ungrounded development",
        recommendedInvestigationStep: "Run MEA memory retrieval or TGA gate discovery."
      });
    }
    return {
      unresolvedQuestions: Object.freeze(questions),
      identifiedGaps: Object.freeze(gaps),
      contradictions: Object.freeze(contradictions)
    };
  }
};

