var OutputGuard = class _OutputGuard {
  /**
   * Evaluates candidate output text for safety boundaries, actuation blocks,
   * and optional hallucination verification.
   */
  static validateOutput(text, options) {
    if (!text || typeof text !== "string") {
      return {
        isSafe: true,
        sanitizedText: ""
      };
    }
    const violations = [];
    const lower = text.toLowerCase();
    const attemptsActuation = (/\b(?:actuate hardware|execute physical command|move robotic arm|switch circuit|fire thruster|trigger actuator|control physical motors|drive motor|actuate motor|move motor)\b/i.test(lower) || /\b(?:actionner le matériel|actionner le materiel|déplacer le bras robotique|deplacer le bras robotique|activer actionneur)\b/i.test(lower) || /\b(?:hardware ansteuern|roboterarm bewegen|motor ansteuern|aktor betätigen)\b/i.test(lower) || /ہارڈویئر\s+کو?\s+چلائیں|روبوٹک\s+بازو|موٹر\s+چلائیں/u.test(lower) || /تشغيل\s+الأجهزة|تحريك\s+الذراع\s+الآلية/u.test(lower) || /执行硬件驱动|移动机械臂|触发执行器|控制物理电机/u.test(lower)) && !/\b(?:permanently blocked|cannot actuate|refuses to actuate|lockout|verrouillé|gesperrt|مقفل|محظور|锁定)\b/i.test(lower);
    if (attemptsActuation) {
      violations.push("HARDWARE_ACTUATION_PROHIBITED");
      return {
        isSafe: false,
        sanitizedText: "[REFUSAL] Refusal: Hardware actuation is permanently blocked in CUBiO AI sovereign runtime. Advisory and analytical outputs only.",
        violations: Object.freeze(violations)
      };
    }
    if (options?.verifier || options?.enableVerification) {
      const verifier = options.verifier ?? new NativeSelfVerifier();
      const auditTrail = verifier.verify(text, {
        tenantId: options.tenantId,
        context: options.context
      });
      if (!auditTrail.isSafeForEmission) {
        violations.push("HALLUCINATION_OR_CONTRADICTION_INTERCEPTED");
      }
      return {
        isSafe: auditTrail.isSafeForEmission,
        sanitizedText: auditTrail.verifiedResponseText,
        violations: violations.length > 0 ? Object.freeze(violations) : void 0,
        auditTrail
      };
    }
    return {
      isSafe: true,
      sanitizedText: text
    };
  }
  /**
   * Explicit pre-emission verification gateway directly wiring NativeSelfVerifier.
   */
  static verifyAndSanitize(text, options) {
    return _OutputGuard.validateOutput(text, {
      ...options,
      enableVerification: true
    });
  }
};

