          problematicSnippet: jsAssignInIf[0],
          correctedCode: fixed,
          fixExplanation: isUrdu ? `'${jsAssignInIf[0]}' ko 'if (${varName} === ${val})' se tabdeel karein.` : `Replace assignment '=' with strict equality comparison '==='.`,
          preventionTip: "Use strict equality `===` in JavaScript and TypeScript."
