var DefectClassifier = class {
  static classify(request, bounds) {
    const errorTrace = (request.errorTrace || "").trim();
    const description = (request.defectDescription || "").trim();
    const code = (request.codeSnippet || "").trim();
    if (!errorTrace && !description && !code) {
      return {
        isValid: false,
        category: "UNKNOWN",
        failureReason: "Defect request is empty: lacks errorTrace, description, and codeSnippet",
        errorCode: "EMPTY_PAYLOAD"
      };
    }
    if (errorTrace.length > bounds.maxErrorTraceLength) {
      return {
        isValid: false,
        category: "UNKNOWN",
        failureReason: `Error trace length (${errorTrace.length}) exceeds maximum limit (${bounds.maxErrorTraceLength})`,
        errorCode: "BOUNDS_EXCEEDED"
      };
    }
    if (code.length > bounds.maxCodeInputLength) {
      return {
        isValid: false,
        category: "UNKNOWN",
        failureReason: `Code snippet length (${code.length}) exceeds maximum limit (${bounds.maxCodeInputLength})`,
        errorCode: "BOUNDS_EXCEEDED"
      };
    }
    const combined = `${errorTrace} ${description}`.toLowerCase();
    if (/ts\d{4}|cannot find name|not assignable|type error|is missing in type|property does not exist/i.test(
      combined
    )) {
      return { isValid: true, category: "COMPILER_TYPESCRIPT" };
    }
    if (/syntaxerror|unexpected token|parsing error|invalid or unexpected token/i.test(combined)) {
      return { isValid: true, category: "SYNTAX_ERROR" };
    }
    if (/assertionerror|expect\(|expected.*to equal|assertion failed|test failed/i.test(combined)) {
      return { isValid: true, category: "TEST_FAILURE" };
    }
    if (/nullpointer|cannot read propert|is not a function|referenceerror|rangeerror|undefined|dereference/i.test(
      combined
    )) {
      return { isValid: true, category: "RUNTIME_EXCEPTION" };
    }
    if (/module not found|cannot resolve module|err_module_not_found/i.test(combined)) {
      return { isValid: true, category: "DEPENDENCY_FAULT" };
    }
    if (/regression|unexpected behavior|infinite loop|overflow/i.test(combined)) {
      return { isValid: true, category: "LOGIC_REGRESSION" };
    }
    return {
      isValid: true,
      category: "UNKNOWN"
    };
  }
};

