// src/cubio/agents/fua/frontendInventoryAdapter.ts
import * as fs37 from "fs";
import * as path36 from "path";
var FrontendInventoryAdapter = class {
  constructor(projectRoot = process.cwd()) {
    this.projectRoot = projectRoot;
  }
  scanFrontendComponents() {
    const targetDirs = [
      path36.join(this.projectRoot, "src", "components"),
      path36.join(this.projectRoot, "src", "cubio", "web", "components"),
      path36.join(this.projectRoot, "src", "cubio", "web", "agents_console"),
      path36.join(this.projectRoot, "src", "cubio", "web")
    ];
    const results = [];
    for (const dir of targetDirs) {
      if (!fs37.existsSync(dir)) continue;
      const entries = fs37.readdirSync(dir, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isFile()) continue;
        if (!entry.name.endsWith(".tsx") && !entry.name.endsWith(".jsx")) continue;
        const fullPath = path36.join(dir, entry.name);
        const relPath = path36.relative(this.projectRoot, fullPath).replace(/\\/g, "/");
        const content = fs37.readFileSync(fullPath, "utf8");
        const componentName = path36.basename(entry.name, path36.extname(entry.name));
        const isModal = componentName.toLowerCase().includes("modal");
        const isView = componentName.toLowerCase().includes("view") || componentName.toLowerCase().includes("app") || componentName.toLowerCase().includes("console");
        const hasIcons = content.includes("lucide-react");
        const hasThreeJs = content.includes("three") || content.includes("@types/three");
        const exportMatches = content.match(/export\s+(?:const|function|class|default)\s+([a-zA-Z0-9_]+)/g) || [];
        const exports = exportMatches.map((m) => m.split(/\s+/).pop() || componentName);
        results.push({
          name: componentName,
          relativePath: relPath,
          isView,
          isModal,
          hasIcons,
          hasThreeJs,
          exports: exports.length > 0 ? exports : [componentName]
        });
      }
    }
    return results;
  }
};

