// src/cubio/agents/dsa/storageContractInspector.ts
var StorageContractInspector = class {
  constructor(inventoryAdapter = new StorageInventoryAdapter()) {
    this.inventoryAdapter = inventoryAdapter;
  }
  auditStorageContracts() {
    const descriptors = this.inventoryAdapter.getStorageServices();
    const findings = [];
    const authoritativeServices = descriptors.filter((d) => d.isAuthoritative);
    if (authoritativeServices.length > 2) {
      findings.push({
        findingId: "FINDING-DUAL-AUTHORITY",
        category: "BOUNDARY",
        severity: "WARNING",
        title: "Multiple Authoritative Storage Endpoints Detected",
        targetComponent: authoritativeServices.map((s) => s.serviceName).join(", "),
        evidence: `Found ${authoritativeServices.length} stores marked authoritative.`,
        recommendation: "Ensure SQLiteDataStore / data/cubio_studio.db remains the exclusive live persistence root."
      });
    }
    const virtAdapter = descriptors.find((d) => d.serviceName.includes("Virtual Data Service"));
    if (virtAdapter && virtAdapter.supportedOperations.includes("getAll")) {
      findings.push({
        findingId: "FINDING-UNBOUNDED-GETALL",
        category: "PERFORMANCE",
        severity: "WARNING",
        title: "Unbounded getAll() Method Exposed in Storage Adapter",
        targetComponent: virtAdapter.sourcePath,
        evidence: "SQLiteStorageAdapter.getAll() retrieves the entire table into memory before filtering.",
        recommendation: "Implement cursor-based pagination or bounded LIMIT queries in SQLiteStorageAdapter."
      });
    }
    const checkpointService = descriptors.find((d) => d.serviceName.includes("Checkpoint Serializer"));
    if (checkpointService && checkpointService.isAuthoritative) {
      findings.push({
        findingId: "FINDING-CHECKPOINT-AUTHORITY-LEAK",
        category: "BOUNDARY",
        severity: "CRITICAL",
        title: "Checkpoint Store Flagged as Authoritative Live Database",
        targetComponent: checkpointService.sourcePath,
        evidence: "Checkpoint bundle is configured as an authoritative live store.",
        recommendation: "Revert checkpoint role to recovery/transport snapshot format."
      });
    }
    return { descriptors, findings };
  }
};

